from pathlib import Path
import re

root = Path(__file__).resolve().parent.parent
draft = (root / '_WORK/HUMAN_DRAFT.md').read_text(encoding='utf-8')
text = draft
changes = []

def edit(prefix, body):
    global text
    matches = [p for p in text.split('\n\n') if p.startswith(prefix)]
    assert len(matches) == 1, (prefix, len(matches))
    old = matches[0]
    refs = re.search(r' \[(?:F|Q|K|E)\d', old)
    suffix = old[refs.start():] if refs else ''
    new = body + suffix
    text = text.replace(old, new, 1)
    changes.append(prefix)

edit('Первая волна включала', '''Первая волна включала шестнадцать отдельных Medium-исследователей: восемь веток по методам M01–M08 и восемь по данным D09–D16. После отдельного High-критика работали семь адресных Medium-веток второй волны. Доказательную базу собрал отдельный High-сборщик; русский текст подготовил High-автор и отредактировал отдельный High-редактор. Для всех этих ролей назначался предусмотренный заданием `gpt-6.1-sol`. Английскую версию готовит отдельный сжиматель. Реальные задания, результаты и переходы сохранены в [_WORK/RUN_STATE.md](_WORK/RUN_STATE.md). Число исследователей описывает организацию работы, а не ансамбль моделей.''')
edit('В этом отчёте различаются восемь', '''Полезно различать восемь ступеней готовности: модель описана; точный обученный файл найден; доступ проверен; полные байты получены и хешированы; схема разобрана; эталонный инференс выполнен; причинные события измерены; точная модель исполнена на LinQ. Исследование дошло до статического разбора моделей, а для части данных — до полного декодирования и ограниченного визуального просмотра. Модели не исполнялись; обучение, экспорт, компиляция и LinQ-тесты не проводились. Статус `local_test` в исходных ветках обычно означает разбор CSV, ZIP, ONNX, TFLite, HDF5, временной шкалы видео или детерминированный подсчёт по аннотациям. Ни один опубликованный benchmark здесь не воспроизводился как проверка качества распознавания.''')
edit('У всех семи замечаний', '''Все семь замечаний критика получили итог `scope_narrowed` — область применимости уточнена. Вторая волна закрыла конкретные пробелы в артефактах и временных привязках, сохранив открытыми численные, событийные, правовые и аппаратные проверки. У K001 теперь есть точный pose-контракт; у K002 — сопоставление четырёх файлов со временем; у K005 — реальная сцена движения техники. До промышленной валидации каждому пути ещё нужны отдельные доказательства. Исходная критика и датированные исходы сохранены в [CRITIC.md](CRITIC.md#K001), без переписывания первоначальных выводов задним числом.''')
edit('Особенно существенен контракт', '''Особенно существенна обработка изображения. Для MMDeploy SDK1.2.0 зафиксированы внешний bbox **xywh**, расширение с padding1.25 до отношения 192/256, округляемый и обрезаемый по границе `CropResizePad`, RGB, mean `[123.675,116.28,103.53]`, std `[58.395,57.12,57.375]`, без дополнительного `/255`. Декодер берёт argmax x/y, делит координаты на 2 и считает score как `min(max_x,max_y)`. Восстановление исходных координат требует center/scale, исправленных после crop. Похожий Python-demo использует BGR и `warpAffine`; его численное отличие от SDK пока неизвестно. Смешение этих путей может испортить первый baseline ещё до квантования и привести к ошибочному выводу о работе модели на LinQ.''')
edit('В официальной recipe person detector', '''В официальном рецепте детектор человека — [RTMDet-nano 05d8511e](https://download.openmmlab.com/mmpose/v1/projects/rtmpose/rtmdet_nano_8xb32-100e_coco-obj365-person-05d8511e.pth). Его 4 224 050 байт получены целиком, SHA256 `05d8511e7b3fabc62e27d2f624179e004ad14ee63a86ca9d9d22c88f3db0eee1`; config задаёт один класс person и вход 320×320. Соответствующий готовый deploy-export здесь не получен. Официальный `rtmpose-cpu.zip` содержит старый детектор `96154d0b`, MMDeploy1.0.0rc1/mmdet3.0.0rc2 и старую pose-модель AIC+COCO. Его отдельный ONNX разобран: в нём есть dynamic-shape/NMS. Это самостоятельный кандидат со своими неизвестными. Для первой сборки нужно экспортировать точный `05d8511e` с закреплёнными зависимостями либо явно выбрать другой проверенный детектор человека.''')
edit('RTMPose-t body7', '''RTMPose-t body7 `026a1439` имеет тот же хеш pipeline и интерфейс, но граф размером 13 350 364 байт и 168 узлов. Это позволяет провести парное сравнение m/t с одинаковыми crop и decode. Скорость и преимущество m на целевой задаче ещё не измерены. Опубликованные показатели m для body7/Body8 выше, однако выбор должен зависеть от видимости суставов дальнего работника, пропусков детектора и ошибок событий. Код MMPose/MMDeploy имеет Apache2; отдельное разрешение именно для body7 и detector weights в ограниченной проверке не найдено. Положительная лицензия кода и открытый вопрос о весах сохраняются раздельно.''')
edit('Есть и альтернативы', '''Альтернативы меняют и условия первого опыта. RTMO-s обрабатывает всё изображение по схеме bottom-up и может быть полезен в плотной сцене, однако COCO `8db55a59` и SDK body7 `dac2bf74` — разные артефакты; доступ проверен только через HEAD. YOLO11n-pose `v8.3.0` удобен как bbox+COCO17 baseline с вопросом AGPL/Enterprise, но выходы экспорта ещё не разобраны. ViTPose-B пригоден для офлайн-сравнения при одинаковых боксах; исходный OneDrive вернул HTML вместо подтверждённых весов. У MoveNet MultiPose максимум шесть одновременных детекций, и настройка трекера его не увеличивает. Актуальный MediaPipe поддерживает `num_poses>1`, по умолчанию 1. При этом старый single-person fitness benchmark не подтверждает работу на промышленной камере, а оценённые hip-relative метры не дают калиброванного расстояния до станка.''')
edit('Первый baseline должен проверять переход', '''Первый baseline проверяет переход по измеренным pose/bbox-наблюдениям и исходным секундам: изменение ориентации и высоты тела, последующее положение и доступную видимость. Сравнение с простым отношением сторон bbox покажет, помогают ли суставы. Обязательные трудные отрицательные примеры — ремонт лёжа, отдых, медленное намеренное укладывание, сидение, наклон, поднятие предмета, приседание и частичная окклюзия. На виде сверху человек может не выглядеть привычно «горизонтальным». Если нос, таз или стопы неразличимы, сам факт выдачи координат не даёт уверенного наблюдения. Здесь нужно измерять общий и своевременный recall переходов, ложные тревоги на полностью просмотренные часы, путаницу падения с укладыванием, ошибку начала, дубли и долю неизвестных интервалов.''')
edit('Готовые небольшие temporal-веса', '''Небольшие обученные временные модели найдены, поэтому вывод «готовых весов нет» был бы неверен. У `udayraj28/fall-detection-vision`, commit `e1c36afa34a966cae087543c01f01646b61141d6`, получены PTH 810 808 B и ONNX 8 228 B **вместе с** external data 807 424 B. Вход — 30×5 признаков: угол hip→nose, CoG y, межкадровый CoG delta, bbox aspect и средняя уверенность pose. Выход — normal/falling/fallen. Код случайно делит уже сформированные перекрывающиеся окна и создаёт часть меток эвристически; README, training report и checkpoint epoch не согласованы. Тридцать кадров равны секунде только при 30 Hz, а delta считается на кадр. Лицензионное разрешение не установлено. После исправления данных и протокола файл может служить сравнительной моделью; 98.2% из README не обосновывают промышленный выбор.''')
edit('Второй пример,', '''Второй пример, `Rchit13`, commit `47b54390988b9aa7e67353b7072be4d735245ac9`, показывает, почему нужно читать train code. README описывает BiLSTM/60frames, а код — plain LSTM128→64, 30frames×24XY. StandardScaler обучается до train/test split; метки берутся из имени файла. MIT относится к коду, pretrained components отдельно описаны как inference-only. Прежде чем включать такой артефакт в доказательство качества, следует проверить, какую нерешённую ошибку простого pose+rules он действительно устраняет.''')
edit('Временной контракт нельзя спрятать', '''Привязку времени нужно зафиксировать явно. Кандидат на порядковый номер BEHAVE — global frame−35450, для CAVIAR — XML frame. После просмотра остаётся неоднозначность ±1; предлагается проверять чувствительность δ−1/0/+1, не выбирая наиболее выгодное смещение. Повторяющиеся PTS в CAVIAR соответствуют новым изображениям: соседних побайтно одинаковых RGB-кадров не найдено. Удаление по одному лишь повтору времени испортит данные. Шкала `i/25` служит синтетическим временем для проверочного воспроизведения; время съёмки она не восстанавливает. Исходные PTS и порядковые номера остаются в журнале.''')
edit('Уже выполненная арифметика', '''Подсчёт по 25 фазам выборки уже показывает цену низкого FPS. На 64 running-кадрах actor7 остаётся 2–3 наблюдения при 1 FPS, 5–6 при 2 FPS и 12–13 при 5 FPS; на 105 кадрах actor6 — 4–5/8–9/21 соответственно. При заданных синтетических 20% потерях некоторые варианты 1 FPS оставляют ноль наблюдений. Максимальная задержка первой возможности наблюдения в проверенной сетке составляет 0.96/0.48/0.16 s — ещё до работы нейросети, накопления окна и подтверждения. Это **возможности наблюдения по разметке**, а не recall распознавания. Допустимый для эксперта 1 FPS нужно проверять отдельно для каждого временного класса.''')
edit('Первый метод — displacement', '''Первый метод измеряет смещение точки контакта или нижней части трека за исходное время внутри настроенной ROI. До калибровки, с учётом нормировки и перспективы, это лишь показатель движения в изображении. Если команда выбирает распознавание бега по походке, нужны различимые ноги, фазы шага и pose/RGB-признаки. Для метрической скорости требуются обследованная плоскость и калибровка. Бег на месте возможен без смещения, а стоящий на движущейся платформе человек смещается без бега. Поэтому в проверку входят быстрая ходьба, переноска, повороты, пересечение людей, короткий рывок, движение камеры или платформы и разная перспектива вблизи и вдали.''')
edit('Конкретный RGB challenger', '''Конкретная RGB-модель для сравнения — [SlowOnly R50 HMDB51](https://download.openmmlab.com/mmaction/recognition/slowonly/slowonly_k400_pretrained_r50_8x4x1_40e_hmdb51_rgb/slowonly_k400_pretrained_r50_8x4x1_40e_hmdb51_rgb_20210630-cee5f725.pth), MMAction2 v0.24.1. Проверен HEAD200, размер 127 223 551 B; полного файла, хеша и запуска нет. Head51 действительно различает zero-based run32/walk49. Config использует 8 кадров с interval4, а исходный тест — 10 temporal clips×ThreeCrop256, всего 30 views. Опубликованные top1 65.95/top5 91.05 относятся ко всем 51 классам HMDB split1. При 25 FPS промежуток от первого до последнего кадра равен 1.12 s; с тем же interval4 при 1 FPS — 28 s. Person crop, окно только из прошедших кадров и другая частота меняют протокол. Модель имеет смысл сравнивать с простым baseline при явной привязке результата к человеку; исходная метрика не гарантирует распознавание конкретного работника.''')
edit('Оригинальный кейс требует телефон', '''Оригинальный кейс требует распознавать телефон при работе с оборудованием **или при перемещении по цеху**. Во втором варианте особенно существенны принадлежность предмета и одновременность действий. UPT-R50 HICO-DET — модель взаимодействий человека с предметами Zhang/Campbell/Gould, CVPR2022, repo `192743045e4c5f6827299fdc15809f5b97ac1b8e`. После штатной confirm-формы Google Drive проверен бинарный ZIP-префикс 4 096 B; заявленный размер — 219 754 181 B. Полного checkpoint нет. UPT выдаёт boxes внутри изображения, pairing[2,M], 117 verbs, 80 objects и scores; идентификаторов треков или событий у него нет. Для cell_phone67 имеются hold36, talk_on101, text_on103, carry8. Carry может сосуществовать с use и не отменяет его. Исходный [UPT-код имеет BSD-3-Clause](https://github.com/fredzzhang/upt/blob/192743045e4c5f6827299fdc15809f5b97ac1b8e/LICENSE). MIT относится к отдельным HICO utilities; права исходных изображений нужно рассматривать отдельно.''')
edit('AVA22 даёт более сильную семантику', '''AVA22 связывает действия с тем же человеком: в скачанном CSV найдено 77 person-second co-labels phone+walk в 27 последовательностях, восьми видео и 24 video-person pairs. Это 77 точек разметки, а не событий. Два выбранных источника `QTmwhrVal1g/person91/1181–1190s` и `WSPvfxtqisg/person1/908–915s` не дали видеопоток: первый сообщает copyright removal, второй — unavailable без причины. Успешный HTTP-ответ с HTML не подтверждает получение видео. Эта недоступность относится к двум проверенным маршрутам и не распространяется на весь AVA.''')
edit('Charades `2RFLZ`', '''Charades `2RFLZ` извлечён из [Charades_v1_480.zip](https://ai2-public-datasets.s3-us-west-2.amazonaws.com/charades/Charades_v1_480.zip), member `Charades_v1_480/2RFLZ.mp4`, размер 765 584 B. Просмотрены все 222 кадра 480×270: человек подходит к столу, поднимает устройство/руку к уху, удерживает позу и возвращает предмет. Контекст указывает на настольный телефон. Исходный интервал c019 3.0–10.4 s шире видимой фазы использования у уха примерно 5.190–8.184 s; убедительная одновременная ходьба и использование не установлены. Исходных phone/person boxes и плотной разметки ходьбы нет. Клип полезен как пример видимого действия, но не закрывает целевую задачу мобильного телефона при движении. AVA-аннотации имеют CC BY4; Charades разрешён для noncommercial research/evaluation, с ограничениями modified-data/public redistribution. Эти разрешения различаются.''')
edit('Связать UPT веса', '''Веса UPT, actor IDs из AVA и интервал Charades описывают разные входные кадры и разную эталонную разметку. Их нельзя соединить в одну проверенную цепочку. Телефон возвращается в MVP после получения разрешённой целевой записи, где у того же человека различимы предмет, использование и одновременная работа или движение. Для проверки нужны радиостанция, сканер, инструмент, поправление защиты, еда/вытирание лица, разрешённый терминал, перенос телефона без использования и дозволенный звонок. Если маленький предмет не получил phone bbox, состояние остаётся неизвестным.''')
edit('Для опасного сближения теперь', '''Для ветки опасного сближения получен реальный ролик с техникой. [SmartSpaces Warehouse_026/Camera_0000](https://huggingface.co/datasets/nvidia/PhysicalAI-SmartSpaces/resolve/2cbe9563cbe9f47f846e5c871ee994572bbbc60e/MTMC_Tracking_2026/test/Warehouse_026/videos/Camera_0000.mp4) скачан целиком: 60 s, 1 800 кадров, 1080p, 30 Hz, SHA256 `83ed232a2f5fe3031807ed19020e1a44fe386e89b68f9bea621797f1552c9cda`. Просмотр каждой секунды и деталей с частотой 5 FPS на 33–41.8 s показывает работников и движущийся управляемый погрузчик/reach-truck. Наблюдаются обычный проезд и совместное присутствие. Опасный инцидент near-miss, метрическая дистанция, TTC, обязанность уступить и нарушение процедуры не установлены.''')
edit('Точный detector [keremberke', '''Точный детектор [keremberke best.pt d8b594…](https://huggingface.co/keremberke/yolov8n-forklift-detection/resolve/d8b594f321dd4c64eda16e435601fd266089fc32/best.pt) получен: 6 216 376 B, SHA256 `0dc3816283226f0f7ac5410620394c8ddeef32c5200b371194ac4df4a1ee7d38`. Без исполнения pickle подтверждена карта `0:forklift,1:person`; у AI City числовой порядок обратный. Модель не определяет водителя, все виды движущихся механизмов или опасность пары. Карточка сообщает авторскую object-detection метрику mAP50 .83794 при 640-input/Ultralytics8.0.21; качество событий на этом видео не измерено. MIT в каталоге — положительное свидетельство лицензирования, однако отдельное разрешение на веса в card не найдено.''')
edit('В release SmartSpaces', '''В release SmartSpaces положительно указаны CC BY4 и возможность скачать первые 60 секунд двух реальных test scenes с calibration, без real GT/depth. Одновременно Croissant/paper сохраняют формулировки hidden-target/privacy/no-training; их применимость к выпущенным отрезкам или другой части данных неизвестна. Правила ручной разметки challenge относятся к протоколу конкретного соревнования и сами по себе не устанавливают универсальный запрет внешнего исследования. Пока область предполагаемого использования не уточнена, этот официальный test следует оставить вне настройки и не считать свободным train для новой разметки. Четыре синхронных вида Warehouse026 и семь Warehouse027 представляют по одной физической минуте, а не одиннадцать независимых часов или событий.''')
edit('Риск-путь требует', '''Для оценки риска нужны треки человека и погрузчика, измеренное движение, связь водителя с техникой, область безопасности конкретной пары и независимая геометрия. Отдельные проверки должны охватывать человека рядом со стоящей техникой, движение вдали, видимого только водителя, задний ход/поворот, разделяющий барьер, закрытые стопы/вилы и разрешённую работу. Калибровочный JSON не устанавливает нормативную безопасную дистанцию. NearCollision6Image6s_027 действительно содержит шесть RGB-кадров и временную цель: первое приближение человека на 1 m к движущейся ego-camera в следующие 6 s. Эта цель отличается от наблюдения пары работник–погрузчик. Два проверенных соседних HDF5-окна делят пять из шести кадров; исходных recording IDs нет. FP-TTC также относится к другой наблюдательной плоскости, а готовые веса здесь не подтверждены. Ветку погрузчика следует оставить резервом до появления pair-event GT и обследованной области безопасности; специально ставить опасные сближения не требуется.''')
edit('Для узкого visible-flame baseline', '''Для узкого детектора видимого пламени подтверждён конкретный артефакт: [rabahdev/fire-smoke-yolov8n best.pt](https://huggingface.co/rabahdev/fire-smoke-yolov8n/resolve/13017fe8af477c25f5298d168e2dfede4b000753/best.pt), revision `13017fe8af477c25f5298d168e2dfede4b000753`, 6 229 802 B, SHA256 `b91633799ceb052c814b4f8b77a37efc9a40f002d528df97d74463585fa4f28f`. Статическая структура подтверждает `0:smoke,1:fire`, card и embedded metadata — AGPL-3.0. Runtime/export/NMS ещё не проверены. Дообучение на D-Fire, 50 epochs/640/batch16/AppleMPS, даёт авторские image test mAP50 .754/mAP50–95 .430. Это другая оценка, чем число ложных тревог за час в цеху. Smoke означает область шлейфа и не назначает владельца-курильщика.''')
edit('MmodalFire полезен', '''MmodalFire полезен непрерывными записями и постановочными контрольными условиями. По заголовкам RAR размером 4.929 GB разобран полный manifest: 103 members, 70 CSV, 28 MP4, worksheet и metadata. Весь архив не получен, опубликованный MD5 локально не проверен. Workbook действительно содержит dry ice Aug4 и mist Aug10; получена Humidifier4 sensor-пара по 22 815 строк. Единственный извлечённый короткий видеофайл длится 42.506 s и относится к Aug2 около 09:33, вне этих sessions. Поэтому **видео mist остаётся UNCONFIRMED**. Сенсоры не заменяют визуальный отрицательный пример, а связь непрозрачных имён файлов с sessions остаётся Q010. Числа 28 raw MP4, 38 settings rows и 65 экспериментов статьи могут обозначать разные единицы; оснований объявлять 65 ошибкой нет. Paper опубликована 19.02.2026, release Figshare — 28.03.2026; дата доступа — 23.10.2026.''')
edit('Перед продвижением пламени', '''Прежде чем включать пламя в MVP, нужно получить непрерывные начало→завершение→повторную готовность системы, реальные пар/пыль/дым без огня, сварку и печь в разрешённой зоне, отражения/экраны, маленькое загорание, перекрытую камеру, а также одинаковое визуальное условие при действующем и недействующем разрешении. Один кабинетный клип не обосновывает порог для всего отрицательного теста. Данные MmodalFire имеют CC BY4, авторский код — MIT; AGPL детектора и условия сторонних источников D-Fire проверяются отдельно. CC0 коллекции D-Fire сохраняет оговорку о правах первоначальных поставщиков изображений.''')
edit('Курение остаётся отдельной', '''Курение остаётся отдельной задачей. В актуальном официальном release HMDB51 есть положительные заявления CC BY4, уточняющие прежнюю неопределённость. Из smoke.rar получены два реальных клипа: `After_work_smoke_in_the_garage…` — 236 кадров, `American_History_X…` — 59 кадров. Это класс smoke на уровне клипа; плотной разметки затяжек, связи человек–сигарета или запрещённой зоны нет. Клип из фильма содержит монтажную склейку. Права исходных фильмов и разбиение по независимым источникам рассматриваются отдельно. Для событийного benchmark курения всё ещё нужны соответствующие наблюдения и разметка.''')

